<style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#f4f6fa;color:#172033}.hidden{display:none!important}.layout{min-height:100vh;display:flex}.side{width:245px;background:#0b0d12;color:#fff;padding:22px 15px;position:fixed;inset:0 auto 0 0;z-index:10}.logo{font-weight:800;letter-spacing:1.5px;font-size:18px;padding:4px 12px 26px}.logo span{color:#6ea8ff}.nav{display:flex;flex-direction:column;gap:7px}.nav button{border:0;background:transparent;color:#9ca3af;text-align:left;padding:12px 14px;border-radius:10px;font:600 13px Inter;cursor:pointer}.nav button i{width:24px}.nav button:hover,.nav button.active{background:#1b1f28;color:#fff}.logout{position:absolute;left:15px;right:15px;bottom:20px}.main{margin-left:245px;width:calc(100% - 245px);padding:28px;max-width:1600px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.top h1{margin:5px 0 0;font-size:28px}.muted{color:#7b8495;font-size:12px}.admin-user{display:flex;align-items:center;gap:10px}.avatar{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:#e7efff;color:#2864d7;font-weight:800}.section{display:none}.section.active{display:block}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:20px}.stat,.panel{background:#fff;border:1px solid #e7eaf0;border-radius:16px;box-shadow:0 8px 30px rgba(15,23,42,.04)}.stat{padding:19px}.stat .ico{width:42px;height:42px;border-radius:11px;background:#edf3ff;color:#2864d7;display:grid;place-items:center;margin-bottom:12px}.stat strong{font-size:25px;display:block}.stat span{display:block;color:#7b8495;font-size:12px;margin-top:4px}.panel{padding:20px;margin-bottom:20px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:16px}.panel-head h2{font-size:16px;margin:0}.actions{display:flex;gap:8px;align-items:center}.btn{border:0;border-radius:9px;padding:10px 13px;font:700 12px Inter;cursor:pointer}.btn.primary{background:#2864d7;color:#fff}.btn.light{background:#eef1f5;color:#374151}.btn.danger{background:#fee2e2;color:#b91c1c}.search{border:1px solid #dce1e8;border-radius:9px;padding:10px 12px;min-width:220px;outline:none}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:760px}.table th{font-size:10px;text-transform:uppercase;color:#8992a2;letter-spacing:.5px;text-align:left;padding:11px 10px;border-bottom:1px solid #edf0f4}.table td{font-size:12px;padding:12px 10px;border-bottom:1px solid #f0f2f5;vertical-align:middle}.thumb{width:55px;height:48px;object-fit:contain;background:#f5f6f8;border-radius:8px}.badge{display:inline-flex;padding:5px 8px;border-radius:999px;font-size:10px;font-weight:700}.badge.pending{background:#fff7d6;color:#a16207}.badge.confirmed{background:#e0f2fe;color:#0369a1}.badge.shipping{background:#ede9fe;color:#6d28d9}.badge.completed{background:#dcfce7;color:#15803d}.badge.cancelled{background:#fee2e2;color:#b91c1c}.chart{height:230px;display:flex;align-items:flex-end;gap:10px;padding:15px 5px 5px}.bar-wrap{height:100%;flex:1;display:flex;align-items:flex-end;justify-content:center;gap:5px}.bar{width:min(35px,70%);min-height:3px;border-radius:7px 7px 2px 2px;background:#2864d7}.bar-label{font-size:9px;color:#8a93a3;text-align:center;margin-top:7px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:flex;flex-direction:column;gap:6px;margin-bottom:12px}.field label{font-size:11px;font-weight:700}.field input,.field textarea,.field select{width:100%;border:1px solid #dce1e8;border-radius:9px;padding:11px;outline:none;font:400 13px Inter;background:#fff}.modal{position:fixed;inset:0;background:rgba(15,23,42,.55);display:grid;place-items:center;padding:20px;z-index:50}.modal-box{width:min(650px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:22px}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.modal-head h2{font-size:18px;margin:0}.order-detail{display:grid;grid-template-columns:1fr 1fr;gap:8px;background:#f7f8fa;padding:14px;border-radius:12px;margin-bottom:14px}.order-detail b{font-size:12px}.mobile-menu{display:none}
@media(max-width:1050px){.cards{grid-template-columns:repeat(2,1fr)}}
@media(max-width:760px){.side{width:70px}.side .logo{font-size:0;padding-left:10px}.side .logo:after{content:'SZ';font-size:17px}.nav button{font-size:0;text-align:center}.nav button i{width:auto;font-size:16px}.logout{font-size:0}.logout i{font-size:15px}.main{margin-left:70px;width:calc(100% - 70px);padding:17px}.top h1{font-size:22px}.cards{grid-template-columns:1fr 1fr}.panel-head{align-items:flex-start;flex-direction:column}.actions{width:100%}.search{width:100%;min-width:0}.grid2{grid-template-columns:1fr}}
</style></head>
<body>
<div id="login" class="modal"><div class="modal-box" style="max-width:410px"><div class="logo" style="color:#111;padding:0 0 18px">2TL</span></div><h2 style="margin:0 0 5px">Admin Dashboard</h2><p class="muted" style="margin-bottom:20px">Đăng nhập để quản lý cửa hàng.</p><form id="loginForm"><div class="field"><label>Tài khoản</label><input id="username" autocomplete="username" required></div><div class="field"><label>Mật khẩu</label><input id="password" type="password" autocomplete="current-password" required></div><button class="btn primary" style="width:100%;padding:12px">Đăng nhập</button></form></div></div>
<div id="app" class="layout hidden"><aside class="side"><div class="logo">2TL </span></div><nav class="nav"><button class="active" data-section="dashboard"><i class="fa-solid fa-chart-pie"></i> Tổng quan</button><button data-section="products"><i class="fa-solid fa-shoe-prints"></i> Sản phẩm</button><button data-section="orders"><i class="fa-solid fa-bag-shopping"></i> Đơn hàng</button><button id="customerNav" class="hidden" data-section="customers"><i class="fa-solid fa-users"></i> Khách hàng</button><button data-section="coupons"><i class="fa-solid fa-ticket"></i> Mã giảm giá</button></nav><button id="logout" class="btn light logout"><i class="fa-solid fa-right-from-bracket"></i> Đăng xuất</button></aside>
<main class="main"><div class="top"><div><div class="muted">2TL / ADMIN</div><h1 id="pageTitle">Tổng quan</h1></div><div class="admin-user"><div class="avatar">A</div><b id="adminName"></b><a id="adminPortal" class="hidden" href="quantri.php">Quản trị viên</a></div></div>
<section id="dashboard" class="section active"><div class="cards"><div class="stat"><div class="ico"><i class="fa-solid fa-shoe-prints"></i></div><strong id="sProducts">0</strong><span>Sản phẩm đang bán</span></div><div class="stat"><div class="ico"><i class="fa-solid fa-box"></i></div><strong id="sStock">0</strong><span>Tổng tồn kho</span></div><div class="stat"><div class="ico"><i class="fa-solid fa-bag-shopping"></i></div><strong id="sOrders">0</strong><span>Tổng đơn hàng</span></div><div class="stat"><div class="ico"><i class="fa-solid fa-coins"></i></div><strong id="sRevenue">0₫</strong><span>Doanh thu đơn hoàn thành</span></div></div><div class="cards"><div class="stat"><strong id="sCustomers">0</strong><span>Khách hàng</span></div><div class="stat"><strong id="sPending">0</strong><span>Đơn chờ xử lý</span></div><div class="stat"><strong id="sLow">0</strong><span>Sản phẩm sắp hết</span></div><div class="stat"><strong id="sToday">0₫</strong><span>Đơn đặt hôm nay đã hoàn thành</span></div></div><div class="panel"><div class="panel-head"><h2>Doanh thu đơn hoàn thành — theo ngày đặt (7 ngày)</h2></div><div id="chart" class="chart"></div></div><div class="panel"><div class="panel-head"><h2>Đơn hàng gần đây</h2><button class="btn light" onclick="showSection('orders')">Xem tất cả</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Khách hàng</th><th>Tổng</th><th>Trạng thái</th><th>Ngày</th></tr></thead><tbody id="recentOrders"></tbody></table></div></div></section>
<section id="products" class="section"><div class="panel"><div class="panel-head"><h2>Quản lý sản phẩm</h2><div class="actions"><input id="productSearch" class="search" placeholder="Tìm sản phẩm..."><button class="btn primary" onclick="openProduct()"><i class="fa-solid fa-plus"></i> Thêm</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Ảnh</th><th>Sản phẩm</th><th>Danh mục</th><th>Giá</th><th>Tồn kho</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody id="productTable"></tbody></table></div></div></section>
<section id="orders" class="section"><div class="panel"><div class="panel-head"><h2>Quản lý đơn hàng</h2><button class="btn light" onclick="loadOrders()"><i class="fa-solid fa-rotate"></i> Làm mới</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Khách hàng</th><th>SĐT</th><th>Tổng</th><th>Trạng thái</th><th>Ngày</th><th></th></tr></thead><tbody id="orderTable"></tbody></table></div></div></section>
<section id="customers" class="section"><div class="panel"><div class="panel-head"><h2>Khách hàng</h2><button class="btn light" onclick="loadCustomers()">Làm mới</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Khách hàng</th><th>Email</th><th>SĐT</th><th>Đơn</th><th>Đã chi</th><th>Trạng thái</th><th></th></tr></thead><tbody id="customerTable"></tbody></table></div></div></section>
<section id="coupons" class="section"><div class="panel"><div class="panel-head"><h2>Mã giảm giá</h2><button class="btn primary" onclick="openCoupon()"><i class="fa-solid fa-plus"></i> Tạo mã</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Giảm</th><th>Lượt dùng</th><th>Trạng thái</th><th></th></tr></thead><tbody id="couponTable"></tbody></table></div></div></section>
</main></div>
<div id="productModal" class="modal hidden"><div class="modal-box"><div class="modal-head"><h2 id="modalTitle">Thêm sản phẩm</h2><button class="btn light" onclick="closeProduct()">✕</button></div><form id="productForm"><input type="hidden" id="pid"><div class="grid2"><div class="field"><label>Tên sản phẩm</label><input id="pname" required></div><div class="field"><label>Danh mục</label><input id="pcat" required placeholder="Chạy bộ / Thời trang..."></div><div class="field"><label>Giá bán</label><input id="pprice" type="number" min="0" required></div><div class="field"><label>Giá cũ</label><input id="pold" type="number" min="0"></div><div class="field"><label>Tồn kho</label><input id="pstock" type="number" min="0" required></div><div class="field"><label>Nhãn</label><input id="pbadge" placeholder="Mới / Hot / -20%"></div></div><div class="field"><label>Đường dẫn ảnh</label><input id="pimage" placeholder="assets/images/product/product-1.3.jpg"></div><div class="field"><label>Mô tả</label><textarea id="pdesc" rows="4"></textarea></div><button class="btn primary">Lưu sản phẩm</button></form></div></div>
<div id="couponModal" class="modal hidden"><div class="modal-box" style="max-width:480px"><div class="modal-head"><h2>Mã giảm giá</h2><button class="btn light" onclick="closeCoupon()">✕</button></div><form id="couponForm"><input type="hidden" id="cid"><div class="field"><label>Mã</label><input id="ccode" required placeholder="WELCOME10"></div><div class="field"><label>Phần trăm giảm (%)</label><input id="cdiscount" type="number" min="0.01" step="0.01" max="100" required></div><div class="field"><label>Số lượt tối đa (0 = không giới hạn)</label><input id="cmax" type="number" min="0" value="0"></div><button class="btn primary">Lưu mã</button></form></div></div>
<div id="detailModal" class="modal hidden"><div class="modal-box" style="max-width:650px"><div class="modal-head"><h2>Chi tiết đơn hàng</h2><button class="btn light" onclick="closeDetail()">✕</button></div><div id="detailContent"></div></div></div>
<script src="api-client.js"></script>
<script>
const $=id=>document.getElementById(id);const money=n=>Number(n||0).toLocaleString('vi-VN')+'₫';const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function api(action,opts={}){const r=await szFetch('api.php?action='+action,{headers:{'Content-Type':'application/json'},...opts});const d=await r.json();if(!r.ok||d.success===false)throw new Error(d.message||'Có lỗi');return d}
const statusText={pending:'Chờ xử lý',confirmed:'Đã xác nhận',shipping:'Đang giao',completed:'Hoàn thành',cancelled:'Đã hủy'};
const transitions={pending:['confirmed','cancelled'],confirmed:['shipping','cancelled'],shipping:['completed','cancelled'],completed:[],cancelled:[]};
function statusSelect(o){const options=[o.status,...(transitions[o.status]||[])];return `<select onchange="changeStatus(${o.id},this.value)" ${options.length===1?'disabled':''} style="padding:6px">${options.map(k=>`<option value="${k}" ${o.status===k?'selected':''}>${statusText[k]}</option>`).join('')}</select>`}
let currentRole='';
async function check(){try{const d=await api('me');if(d.loggedIn){$('login').classList.add('hidden');$('app').classList.remove('hidden');$('adminName').textContent=d.name;currentRole=d.role;$('customerNav').classList.toggle('hidden',d.role!=='admin');$('adminPortal').classList.toggle('hidden',d.role!=='admin');loadAll()}}catch(e){alert(e.message)}}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})});location.reload()}catch(e){alert(e.message)}};
$('logout').onclick=async()=>{await api('logout');location.reload()};
function showSection(id){if(id==='customers'&&currentRole!=='admin')return;document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.section===id));$('pageTitle').textContent={dashboard:'Tổng quan',products:'Sản phẩm',orders:'Đơn hàng',customers:'Khách hàng',coupons:'Mã giảm giá'}[id];({products:loadProducts,orders:loadOrders,customers:loadCustomers,coupons:loadCoupons}[id]||(()=>{}))()}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showSection(b.dataset.section));
async function loadStats(){const d=await api('stats'),s=d.stats;$('sProducts').textContent=s.products;$('sStock').textContent=s.stock;$('sOrders').textContent=s.orders;$('sRevenue').textContent=money(s.revenue);$('sCustomers').textContent=s.customers;$('sPending').textContent=s.pending;$('sLow').textContent=s.low_stock;$('sToday').textContent=money(s.today_revenue)}
async function loadChart(){const d=await api('revenue_chart');const max=Math.max(1,...d.data.map(x=>Number(x.revenue)));$('chart').innerHTML=d.data.map(x=>`<div class="bar-wrap"><div style="width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end"><div class="bar" title="${money(x.revenue)}" style="height:${Math.max(2,Number(x.revenue)/max*85)}%"></div><div class="bar-label">${x.day.slice(5)}</div></div></div>`).join('')||'<span class="muted">Chưa có dữ liệu doanh thu.</span>'}
async function loadOrders(){const d=await api('orders'),rows=d.orders;$('orderTable').innerHTML=rows.map(o=>`<tr><td><b>#${o.id}</b></td><td><b>${esc(o.customer_name)}</b><br><span class="muted">${esc(o.email||'')}</span></td><td>${esc(o.phone)}</td><td><b>${money(o.total)}</b></td><td>${statusSelect(o)}</td><td>${new Date(o.created_at).toLocaleString('vi-VN')}</td><td><button class="btn light" onclick="showOrder(${o.id})">Chi tiết</button></td></tr>`).join('')||'<tr><td colspan="7">Chưa có đơn hàng.</td></tr>';$('recentOrders').innerHTML=rows.slice(0,5).map(o=>`<tr><td>#${o.id}</td><td>${esc(o.customer_name)}</td><td>${money(o.total)}</td><td><span class="badge ${o.status}">${statusText[o.status]}</span></td><td>${new Date(o.created_at).toLocaleDateString('vi-VN')}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có đơn hàng.</td></tr>'}
async function changeStatus(id,status){try{await api('update_order',{method:'POST',body:JSON.stringify({id,status})});loadOrders();loadStats();loadChart()}catch(e){alert(e.message)}}
async function showOrder(id){try{const d=await api('order_detail&id='+id);const o=d.order;$('detailContent').innerHTML=`<div class="order-detail"><div><span class="muted">Mã đơn</span><br><b>#${o.id}</b></div><div><span class="muted">Ngày</span><br><b>${new Date(o.created_at).toLocaleString('vi-VN')}</b></div><div><span class="muted">Khách hàng</span><br><b>${esc(o.customer_name)}</b></div><div><span class="muted">Email</span><br><b>${esc(o.email||'')}</b></div><div><span class="muted">SĐT</span><br><b>${esc(o.phone)}</b></div><div><span class="muted">Địa chỉ</span><br><b>${esc(o.address)}</b></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Sản phẩm</th><th>Size</th><th>SL</th><th>Giá</th></tr></thead><tbody>${d.items.map(i=>`<tr><td>${esc(i.product_name)}</td><td>${esc(i.size)}</td><td>${i.quantity}</td><td>${money(i.price)}</td></tr>`).join('')}</tbody></table></div><div style="text-align:right;margin-top:15px"><b>Tổng: ${money(o.total)}</b></div>`;$('detailModal').classList.remove('hidden')}catch(e){alert(e.message)}}
function closeDetail(){$('detailModal').classList.add('hidden')}
let productCache=[];async function loadProducts(){const d=await api('products_admin');productCache=d.products;renderProducts(productCache)}
function renderProducts(rows){$('productTable').innerHTML=rows.map(p=>`<tr><td><img class="thumb" src="${esc(p.image)}" onerror="this.style.opacity=.25"></td><td><b>${esc(p.name)}</b><br><span class="muted">${esc(p.badge||'')}</span></td><td>${esc(p.category)}</td><td><b>${money(p.price)}</b></td><td>${p.stock}</td><td>${p.status==1?'<span class="badge completed">Đang bán</span>':'<span class="badge cancelled">Đã ẩn</span>'}</td><td><div class="actions"><button class="btn light" onclick="editProduct(${Number(p.id)})">Sửa</button>${p.status==1?`<button class="btn danger" onclick="deleteProduct(${p.id})">Ẩn</button>`:`<button class="btn light" onclick="restoreProduct(${p.id})">Hiện</button>`}</div></td></tr>`).join('')||'<tr><td colspan="7">Chưa có sản phẩm.</td></tr>'}
$('productSearch').oninput=e=>{const q=e.target.value.toLowerCase();renderProducts(productCache.filter(p=>p.name.toLowerCase().includes(q)||p.category.toLowerCase().includes(q)))};
function editProduct(id){openProduct(productCache.find(p=>Number(p.id)===id))}
function openProduct(p=null){$('productModal').classList.remove('hidden');$('modalTitle').textContent=p?'Sửa sản phẩm':'Thêm sản phẩm';$('pid').value=p?.id||'';$('pname').value=p?.name||'';$('pcat').value=p?.category||'';$('pprice').value=p?.price||'';$('pold').value=p?.old_price||'';$('pstock').value=p?.stock||0;$('pbadge').value=p?.badge||'';$('pimage').value=p?.image||'';$('pdesc').value=p?.description||''}function closeProduct(){$('productModal').classList.add('hidden')}
$('productForm').onsubmit=async e=>{e.preventDefault();const d={id:+$('pid').value||0,name:$('pname').value,category:$('pcat').value,price:+$('pprice').value,old_price:+$('pold').value,stock:+$('pstock').value,badge:$('pbadge').value,image:$('pimage').value,description:$('pdesc').value};try{await api('save_product',{method:'POST',body:JSON.stringify(d)});closeProduct();loadProducts();loadStats()}catch(e){alert(e.message)}};
async function deleteProduct(id){if(!confirm('Ẩn sản phẩm khỏi website?'))return;try{await api('delete_product&id='+id);loadProducts();loadStats()}catch(e){alert(e.message)}}async function restoreProduct(id){try{await api('restore_product&id='+id);loadProducts();loadStats()}catch(e){alert(e.message)}}
async function loadCustomers(){if(currentRole!=='admin')return;const d=await api('customers');$('customerTable').innerHTML=d.customers.map(c=>`<tr><td><b>${esc(c.full_name)}</b></td><td>${esc(c.email)}</td><td>${esc(c.phone||'—')}</td><td>${c.orders}</td><td>${money(c.spent)}</td><td>${c.status==1?'<span class="badge completed">Hoạt động</span>':'<span class="badge cancelled">Đã khóa</span>'}</td><td><button class="btn light" onclick="toggleCustomer(${c.id})">${c.status==1?'Khóa':'Mở khóa'}</button></td></tr>`).join('')||'<tr><td colspan="7">Chưa có khách hàng.</td></tr>'}async function toggleCustomer(id){try{await api('toggle_customer&id='+id);loadCustomers()}catch(e){alert(e.message)}}
let couponCache=[];async function loadCoupons(){const d=await api('coupons');couponCache=d.coupons;$('couponTable').innerHTML=d.coupons.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${c.discount_percent}%</td><td>${c.used_count}${c.max_uses>0?' / '+c.max_uses:' / ∞'}</td><td>${c.status==1?'<span class="badge completed">Đang dùng</span>':'<span class="badge cancelled">Tắt</span>'}</td><td><div class="actions"><button class="btn light" onclick="editCoupon(${Number(c.id)})">Sửa</button><button class="btn ${c.status==1?'danger':'light'}" onclick="toggleCoupon(${c.id})">${c.status==1?'Tắt':'Bật'}</button></div></td></tr>`).join('')||'<tr><td colspan="5">Chưa có mã giảm giá.</td></tr>'}
function editCoupon(id){openCoupon(couponCache.find(c=>Number(c.id)===id))}
function openCoupon(c=null){$('couponModal').classList.remove('hidden');$('cid').value=c?.id||'';$('ccode').value=c?.code||'';$('ccode').readOnly=Boolean(c);$('cdiscount').value=c?.discount_percent||'';$('cmax').value=c?.max_uses||0}function closeCoupon(){$('couponModal').classList.add('hidden')}
$('couponForm').onsubmit=async e=>{e.preventDefault();try{await api('save_coupon',{method:'POST',body:JSON.stringify({id:+$('cid').value||0,code:$('ccode').value,discount_percent:+$('cdiscount').value,max_uses:+$('cmax').value})});closeCoupon();loadCoupons()}catch(e){alert(e.message)}};async function toggleCoupon(id){try{await api('toggle_coupon&id='+id);loadCoupons()}catch(e){alert(e.message)}}
async function loadAll(){try{await Promise.all([loadStats(),loadChart(),loadOrders(),loadProducts()])}catch(e){alert(e.message)}}
check();
</script></body></html>
